// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// "Show if" conditions of the chat (`show_if` on the home's link and
// announcement cards and on the guided flow's buttons; the server evaluates
// the same schema for the proactive messages):
//
//   { "match": "all" | "any",
//     "rules": [{ "fact": "plan", "operator": "is", "value": "premium" }] }
//
// A rule reads one fact about the visitor: `signed_in` ("true" / "false"),
// what the app says of its user (the SDK's `updateUser`) and why it opened
// the chat (the SDK's `present({ context })`, which wins on a shared name).
// Every value is compared as text, trimmed and case-insensitively; a missing
// or blank fact is "missing". No condition, or one without rules, always
// holds. Pure functions: no React, no network.

export type ConditionOperator =
  | "is"
  | "is_not"
  | "contains"
  | "is_set"
  | "is_not_set"
  | "greater_than"
  | "less_than";

export interface ConditionRule {
  fact: string;
  operator: ConditionOperator;
  value: string | null;
}

export interface ShowIf {
  match: "all" | "any";
  rules: ConditionRule[];
}

// Fact name -> value as text.
export type ConditionFacts = Readonly<Record<string, string>>;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function scalarText(value: unknown): string | null {
  if (typeof value === "string") return value;
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  if (typeof value === "boolean") return value ? "true" : "false";
  return null;
}

// A stored `show_if`, read defensively (the server validates it on save, a
// preview draft is not): null when there is nothing to check. An operator we
// do not know is kept, and its rule never holds.
export function parseShowIf(raw: unknown): ShowIf | null {
  if (!isRecord(raw) || !Array.isArray(raw.rules)) return null;
  const rules = raw.rules.flatMap((rule): ConditionRule[] => {
    if (!isRecord(rule) || typeof rule.fact !== "string" || !rule.fact.trim()) return [];
    return [
      {
        fact: rule.fact.trim(),
        operator: (typeof rule.operator === "string" ? rule.operator : "") as ConditionOperator,
        value: scalarText(rule.value),
      },
    ];
  });
  if (rules.length === 0) return null;
  return { match: raw.match === "any" ? "any" : "all", rules };
}

function normalized(value: string): string {
  return value.trim().toLowerCase();
}

function numberOf(value: string): number | null {
  const trimmed = value.trim();
  if (!/^[-+]?(\d+\.?\d*|\.\d+)$/.test(trimmed)) return null;
  const number = Number(trimmed);
  return Number.isFinite(number) ? number : null;
}

function compare(actual: string, expected: string, operator: "greater_than" | "less_than"): boolean {
  const a = numberOf(actual);
  const b = numberOf(expected);
  if (a === null || b === null) return false;
  return operator === "greater_than" ? a > b : a < b;
}

export function ruleHolds(rule: ConditionRule, facts: ConditionFacts): boolean {
  const raw = Object.prototype.hasOwnProperty.call(facts, rule.fact) ? facts[rule.fact] : undefined;
  const actual = typeof raw === "string" && raw.trim() ? raw : null;
  const expected = rule.value ?? "";
  switch (rule.operator) {
    case "is":
      return actual !== null && normalized(actual) === normalized(expected);
    case "is_not":
      return actual === null || normalized(actual) !== normalized(expected);
    case "contains":
      return actual !== null && normalized(actual).includes(normalized(expected));
    case "is_set":
      return actual !== null;
    case "is_not_set":
      return actual === null;
    case "greater_than":
    case "less_than":
      return actual !== null && compare(actual, expected, rule.operator);
    default:
      return false;
  }
}

export function showIfHolds(showIf: ShowIf | null, facts: ConditionFacts): boolean {
  if (!showIf || showIf.rules.length === 0) return true;
  return showIf.match === "any"
    ? showIf.rules.some((rule) => ruleHolds(rule, facts))
    : showIf.rules.every((rule) => ruleHolds(rule, facts));
}

// The facts a visitor's conditions read: `signed_in`, then the app's
// attributes, then the opening context (later wins). An attribute or a
// context key named `signed_in` is ignored: only the chat says who is
// signed in.
export function conditionFacts(input: {
  signedIn: boolean;
  attributes?: Readonly<Record<string, unknown>> | null;
  context?: Readonly<Record<string, unknown>> | null;
}): ConditionFacts {
  const facts: Record<string, string> = {};
  for (const source of [input.attributes, input.context]) {
    for (const [key, value] of Object.entries(source ?? {})) {
      const text = scalarText(value);
      if (text !== null) facts[key] = text;
    }
  }
  facts.signed_in = input.signedIn ? "true" : "false";
  return facts;
}
